import anthropic

MODEL = "claude-opus-5-5"   # model names change; check the models overview
client = anthropic.Anthropic()

message = client.messages.create(
    model=MODEL,
    max_tokens=500,
    messages=[
        {"role": "user", "content": "Give me three names for a pet tortoise."}
    ],
)

for block in message.content:
    if block.type == "text":
        print(block.text)

import anthropic

client = anthropic.Anthropic()
resp = client.messages.create(
    model="claude-opus-5-5",
    max_tokens=2048,
    tools=[{
        "type": "web_search_20260318",   # versioned; check the docs
        "name": "web_search",
        "max_uses": 3,
    }],
    messages=[{"role": "user", "content": "What changed in the latest Python release?"}],
)

for block in resp.content:
    if block.type == "server_tool_use":
        print("searched:", block.input["query"])
    elif block.type == "text":
        print(block.text)
        for c in block.citations or []:
            print("  source:", c.url)

import time
import anthropic

client = anthropic.Anthropic()
reviews = {"r1": "Loved it!", "r2": "Broke after a day.", "r3": "It's fine."}

batch = client.messages.batches.create(requests=[
    {"custom_id": rid, "params": {
        "model": "claude-haiku-5-5", "max_tokens": 5,
        "messages": [{"role": "user", "content":
            f"Sentiment (positive/negative/neutral), one word: {text}"}]}}
    for rid, text in reviews.items()
])

while client.messages.batches.retrieve(batch.id).processing_status != "ended":
    time.sleep(60)

for item in client.messages.batches.results(batch.id):
    if item.result.type == "succeeded":
        print(item.custom_id, item.result.message.content[0].text)
    else:
        print(item.custom_id, "->", item.result.type)

# pip install claude-agent-sdk   (uses ANTHROPIC_API_KEY)
import asyncio
from claude_agent_sdk import (query, ClaudeAgentOptions,
                              AssistantMessage, ResultMessage, TextBlock)

async def main():
    options = ClaudeAgentOptions(
        system_prompt="You are a careful code reviewer.",
        allowed_tools=["Read", "Grep", "Glob"],   # read-only tools run freely
        permission_mode="default",
        cwd="./my_project",
        max_turns=10,
    )
    async for msg in query(prompt="Find likely bugs in utils.py", options=options):
        if isinstance(msg, AssistantMessage):
            for block in msg.content:
                if isinstance(block, TextBlock):
                    print(block.text)
        elif isinstance(msg, ResultMessage):
            print("done:", msg.subtype, "cost $", msg.total_cost_usd)

asyncio.run(main())
